"""
Pydantic schemas for Personalized Career Roadmaps.
"""

from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field


class AIRoadmapItemPayload(BaseModel):
    """Individual item generated by Ollama LLM."""

    phase: str = Field(..., description="Phase title, e.g., 'Phase 1: Core Technical Prerequisites'")
    skill: str = Field(..., description="Target skill name")
    topics: list[str] = Field(default_factory=list, description="Key topics to study")
    projects: list[str] = Field(default_factory=list, description="Practical portfolio project ideas")
    resources: list[str] = Field(default_factory=list, description="Trusted study topics/documentation guides")
    priority: str = Field("High", description="High, Medium, or Low priority")
    estimated_effort: str = Field("2 weeks", description="Estimated duration or hours")


class AIRoadmapPromptPayload(BaseModel):
    """Full roadmap payload generated by Ollama."""

    title: str = Field(..., description="Roadmap title")
    items: list[AIRoadmapItemPayload] = Field(default_factory=list)


class GenerateRoadmapRequest(BaseModel):
    """Request payload to trigger roadmap generation."""

    occupation_id: int | None = Field(None, description="Optional target occupation ID")
    custom_query: str | None = Field(None, description="Optional custom target role, language, skill, or project entered by candidate")



class RoadmapItemResponse(BaseModel):
    """Roadmap item schema for API responses."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    roadmap_id: int
    phase: str
    skill: str
    topics: list[str] = Field(default_factory=list)
    projects: list[str] = Field(default_factory=list)
    resources: list[str] = Field(default_factory=list)
    priority: str
    estimated_effort: str
    is_completed: bool
    completed_at: datetime | None = None


class RoadmapResponse(BaseModel):
    """Complete career roadmap response."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    user_id: int
    occupation_id: int | None = None
    title: str
    target_role: str
    overall_progress: float
    is_active: bool
    items: list[RoadmapItemResponse] = Field(default_factory=list)
    current_skills: list[str] = Field(default_factory=list)
    missing_skills: list[str] = Field(default_factory=list)
    created_at: datetime
    updated_at: datetime
